-- Helper Functions

function defaultStr(value)
    return value and " " .. value or ""
end

function debugUnicode(str, varName)
    varName = varName or "Unicode string"  -- Default to "Unicode string" if no varName is provided

    if not str then
        print(varName .. ": nil (No string provided)")
        return
    end

    if #str == 0 then
        print(varName .. ": (Empty string)")
        return
    end

    print(varName .. ": " .. str)
    for i = 1, #str do
        local byte = string.byte(str, i)

        -- Handle invalid byte, e.g., for multi-byte characters
        if byte then
            print(string.format("Unicode Codepoint %d: U+%04X", i, byte))
        else
            print(string.format("Unicode Codepoint %d: Invalid byte", i))
        end
    end
end

function debugMenuItem(application, element, description)
    local names = element:actionNames()
    if names then
        for i, name in ipairs(names) do
            print(defaultStr(application:name()) .. " " .. i ..". ".. defaultStr(element.AXTitle) .. defaultStr(element.AXValue) .. defaultStr(element.AXDescription).. defaultStr(element.AXHelp).. ' - "' .. name .. '": ' .. element:actionDescription(name))
        end
    end

end

function debugElement(element, description)
    if description then
        print("Check element: ".. description)
    end
    if not element then
        print("  Error: no element exists")
        return
    end

    if not element['attributeNames'] then
        print("  Error: element:attributeNames() not exists")
        return
    end

    local attributeNames = element:attributeNames()
    if attributeNames then
        for i, v in pairs(attributeNames) do
            local o = element:attributeValue(v)
            print("attributeValue " .. i .. ". " .. v .. ": " .. hs.inspect(o))
        end
    end

    local parameterizedAttributeNames = element:parameterizedAttributeNames()
    --     logger.i(inspect(currentElement:parameterizedAttributeNames()))
    if parameterizedAttributeNames then
        for i, name in ipairs(parameterizedAttributeNames) do
            print("parameterizedAttributeNames " .. i .. ". " .. name .. ': ' .. hs.inspect(element:parameterizedAttributeValue(name, {})))
        end
    end

    -- see more: https://github.com/dbalatero/dotfiles/blob/88db55576616a697e81cbc7478eecbec5672a22e/hammerspoon/experimental.lua#L267

    print('--------------------')
    print('action names:')
    local names = element:actionNames()
    print(hs.inspect(names))
    print('--------------------')
    print('action descriptions:')

    if names then
        for i, name in ipairs(names) do
            print("actionDescription " .. i .. '.  "' .. name .. '": ' .. (element:actionDescription(name) or '{null}'))
        end
    end

    print('Children:' .. hs.inspect(element:attributeValue('AXChildren')))

    -- more debugging in https://github.com/dbalatero/dotfiles/blob/master/hammerspoon/experimental.lua#L424


end

function debugInfo(...)
    local info = ""

    -- not work for args :( breaks on nil value
    -- for index, value in ipairs({...}) do

    local arg = { ... }
    for index = 1, #arg do
        local value = arg[index]
        if value == nil then
            info = info .. '<nil>'
        else
            if type(value) == 'string' then
                info = info .. value
            else
                info = info .. hs.inspect(value)
            end
        end
    end
    print(info)
end

function debugTable(obj)
    print(dumpTableToString(obj))
end

function dumpTableToString(o, level)
    if level == nil then
        level = 1
    end
    local showCounter = false
    local intend = string.rep('  ', level)
    if type(o) == 'table' then
        local info = {}
        for k, v in pairs(o) do
            if type(k) ~= 'number' then
                --k = '  ["'..k..'"] = '
                k = '  ' .. k .. ' = '
            else
                k = '  '
            end
            table.insert(info, intend .. k .. dumpTableToString(v, level + 1))

            --if type(k) ~= 'number' then k = '"'..k..'"' end
            --table.insert(info, intend.. '  ['..k..'] = ' .. dumpTableToString(v, level+1))
        end

        local s
        if #info > 0 then
            local counter = (showCounter and ('<' .. #info .. '>') or '')
            s = counter .. '{\n' .. table.concat(info, ',\n') .. '\n' .. intend .. '}'
        else
            s = '{}'
        end

        return s
    else
        --return tostring(o)
        return hs.inspect(o)
    end
end

function debugTraceback ()
    local level = 1
    while true do
        local info = debug.getinfo(level, "Sl")
        if not info then
            break
        end
        if info.what == "C" then
            -- is a C function?
            print(level, "C function")
        else
            -- a Lua function
            print(string.format("[%s]:%d",
                    info.short_src, info.currentline))
        end
        level = level + 1
    end
end

function debugTracePrint(event, line)
    local info = debug.getinfo(2, "Sl")

    if info.source:startsWith("@/Application") then
        return
    end

    local source = ReadLine(info.source, line) or ""

    print(info.short_src .. ":" .. line .. " " .. source)
end

---
--- Starts a global Lua line trace.
---
--- WARNING:
--- This traces every executed Lua line across the entire Hammerspoon
--- runtime, including timers, watchers, callbacks and loaded modules.
--- It generates huge log files and can significantly slow down
--- Hammerspoon.
---
--- Only enable it briefly and always call debugTraceStop() afterwards.
---
--- Example:
---
---     debugTrace()
---     someFunction()
---     debugTraceStop()
---
--- Or stop tracing automatically after one second:
---
---     debugTrace()
---
---     hs.timer.doAfter(1, function()
---         debugTraceStop()
---         print("debugTrace stopped")
---     end)
---
function debugTrace()
    debug.sethook(debugTracePrint, "l")
end

---
--- Stops the global Lua line trace.
---
function debugTraceStop()
    debug.sethook()
end

---
--- Executes a function while Lua line tracing is enabled.
---
--- The trace is stopped automatically, even when the function raises
--- an error. Function arguments and multiple return values are preserved.
---
--- Example:
---
---     debugTraceFunction(someFunction)
---
---     debugTraceFunction(someFunction, arg1, arg2)
---
---     local result = debugTraceFunction(function()
---         return someFunction()
---     end)
---
function debugTraceFunction(fn, ...)
    local results

    debugTrace()

    results = table.pack(
        xpcall(fn, debug.traceback, ...)
    )

    debugTraceStop()

    if not results[1] then
        error(results[2], 0)
    end

    return table.unpack(results, 2, results.n)
end
